"use strict";
/* DANI · quotes-data.js
   داده‌ی جمله‌ها (دوزبانه) و جمله‌ی بنر تم
   فایل‌های js/ به ترتیب در index.html بارگذاری می‌شوند و متغیرها و تابع‌ها را مشترک دارند (مثل یک فایل واحد). */
/* ===== Quote packs (bilingual, data only) + theme banner quote ===== */
const QPACKS={};let HQ_SEED=Math.floor(Math.random()*1e6);
function qpVet(o){const E=m=>({err:m}),S=(v,n)=>v==null||(typeof v==='string'&&v.length<=n);
 if(!o||typeof o!=='object'||Array.isArray(o)||o.format!=='dani-quotepack'||o.version!==1)return E('این فایل بسته‌ی جملات DANI نیست (format/version)');
 if(typeof o.id!=='string'||!/^[a-z][a-z0-9_-]{1,23}$/.test(o.id))return E('شناسه‌ی بسته نامعتبر است');
 if(typeof o.name!=='string'||!o.name.trim()||o.name.length>40)return E('نام بسته نامعتبر است');
 if(o.character!=null&&(typeof o.character!=='string'||!/^[a-z][a-z0-9_-]{1,23}$/.test(o.character)))return E('character نامعتبر است');
 if(!S(o.author,60))return E('author نامعتبر است');
 if(!Array.isArray(o.quotes)||!o.quotes.length||o.quotes.length>1000)return E('quotes باید بین ۱ تا ۱۰۰۰ جمله باشد');
 const q=[],seen=new Set();for(const x of o.quotes){if(!x||typeof x!=='object'||typeof x.fa!=='string'||!x.fa.trim()||x.fa.length>300||!S(x.en,300)||!S(x.a,60)||!S(x.src,80)||!S(x.note,200))return E('جمله‌ی نامعتبر: '+String(x&&x.fa).slice(0,30));const fa=x.fa.trim();if(seen.has(fa))continue;seen.add(fa);q.push({fa,en:(x.en||'').trim(),a:(x.a||'').trim(),src:(x.src||'').trim(),note:(x.note||'').trim()})}
 return{pack:{id:o.id,name:o.name.trim(),character:o.character||'',author:(o.author||'').trim(),quotes:q}}}
function qpQ(p,i){const q=p.quotes[i];return{id:'q_'+p.id+'_'+i,t:q.fa,en:q.en,c:'pk_'+p.id,a:q.a||p.author||p.name,src:q.src||p.name,kind:'tv',note:q.note,x:true,pk:p.id}}
function qPackAll(){const r=[];Object.values(QPACKS).forEach(p=>p.quotes.forEach((_,i)=>r.push(qpQ(p,i))));return r}
function qpRegister(p){QPACKS[p.id]=p;try{QTOP['pk_'+p.id]=p.name}catch(e){}}
async function qpSave(id,p){const v=JSON.stringify(p);try{await IMG.set('qpack_'+id,v);return'idb'}catch(e){}try{localStorage.setItem('dani_qpack_'+id,v);return'ls'}catch(e){}return'mem'}
async function qpBoot(){let n=0;const raw=[];try{for(const k of await IMG.keys())if(typeof k==='string'&&k.startsWith('qpack_'))raw.push(await IMG.get(k))}catch(e){}try{for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&k.startsWith('dani_qpack_'))raw.push(localStorage.getItem(k))}}catch(e){}
 raw.forEach(r=>{try{const v=qpVet(Object.assign({format:'dani-quotepack',version:1},JSON.parse(r)));if(v.pack){qpRegister(v.pack);n++}}catch(e){}});if(n)render()}
async function qpImport(f){try{if(f.size>3e6)return toast('فایل بزرگ‌تر از ۳ مگابایت است',1);const v=qpVet(JSON.parse(await f.text()));if(v.err)return toast('بسته‌ی جملات رد شد: '+v.err,1);
 const p=v.pack,old=QPACKS[p.id];let add=p.quotes.length;if(old){const have=new Set(old.quotes.map(q=>q.fa)),nw=p.quotes.filter(q=>!have.has(q.fa));add=nw.length;p.quotes=old.quotes.concat(nw);if(!p.character)p.character=old.character}
 if(p.quotes.length>2000)return toast('هر بسته حداکثر ۲۰۰۰ جمله دارد',1);
 const sv=await qpSave(p.id,p);qpRegister(p);if(save()){toast(sv==='mem'?'جمله‌ها فقط برای همین نشست اضافه شد؛ مرورگر اجازه‌ی ذخیره نداد':'«'+p.name+'»: '+fa(add)+' جمله‌ی تازه اضافه شد',sv==='mem'?1:0);render()}}catch(x){console.error(x);toast('وارد کردن بسته‌ی جملات ممکن نشد: '+(x.message||x),1)}}
function heroCfg(){const c=Object.assign({mode:'rot',src:'char',iv:40,open:true,bi:false,en:true,au:true},db.set.heroq&&typeof db.set.heroq==='object'?db.set.heroq:{});if(c.mode==='random')c.mode='rot';return c}
function heroPool(ch){const r=[];if(ch==='eren')ERN_Q.forEach((a,i)=>r.push({id:'en'+i,fa:a[0],en:a[1],a:a[2]}));if(ch==='itachi')ITU_Q.forEach((a,i)=>r.push({id:'h'+i,fa:a[0],en:a[1],a:'Itachi Uchiha'}));Object.values(QPACKS).forEach(p=>{if(p.character===ch)p.quotes.forEach((_,i)=>{const q=qpQ(p,i);r.push({id:q.id,fa:q.t,en:q.en,a:q.a})})});return r}
function hqPool(ch){const c=heroCfg(),Q=zQT();let P=heroPool(ch);
 if(c.src==='all'){const seen=new Set(P.map(x=>x.id));qAll().filter(q=>!Q.hidden.includes(q.id)).forEach(q=>{if(!seen.has(q.id))P.push({id:q.id,fa:q.t,en:q.en||'',a:q.a||''})})}
 else if(c.src==='fav'){const M=qMap(),F=Q.fav.map(i=>M[i]).filter(Boolean).map(q=>({id:q.id,fa:q.t,en:q.en||'',a:q.a||''}));if(F.length)P=F}
 if(c.bi){const B=P.filter(x=>x.en);if(B.length)P=B}return P}
function hqState(){const s=db.set.hqst;return s&&Array.isArray(s.h)?s:{h:[],p:-1,ts:0}}
let HQ_OPENED=false;
function hqDue(){const c=heroCfg(),s=hqState();return c.mode==='rot'&&s.p===s.h.length-1&&c.iv>0&&Date.now()-s.ts>=c.iv*60000}
function hqPick(P){const s=hqState(),recent=s.h.slice(-Math.min(20,Math.max(0,P.length-1))),C=P.filter(q=>!recent.includes(q.id)),L=C.length?C:P,q=L[Math.floor(Math.random()*L.length)];s.h.push(q.id);if(s.h.length>60)s.h.shift();s.p=s.h.length-1;s.ts=Date.now();db.set.hqst=s;save();HQ_OPENED=true;return q}
function heroQuote(ch){const P=hqPool(ch),c=heroCfg();if(!P.length)return{fa:'',en:'',a:'',id:''};
 if(c.mode==='pin'){const q=P.find(x=>x.id===c.pin);if(q)return q}
 if(c.mode==='daily'||c.mode==='pin'){const d=new Date();return P[(d.getFullYear()*372+d.getMonth()*31+d.getDate())%P.length]}
 const s=hqState(),cur=P.find(x=>x.id===s.h[s.p]);if(cur&&!hqDue()&&(HQ_OPENED||!c.open||s.p!==s.h.length-1)){HQ_OPENED=true;return cur}return hqPick(P)}
function hqNav(m,ch){const P=hqPool(ch);if(!P.length)return;const c=heroCfg();if(c.mode!=='rot'){const cur=heroQuote(ch);db.set.heroq=Object.assign({},c,{mode:'rot'});const s=hqState();if(cur&&cur.id&&s.h[s.p]!==cur.id){s.h.push(cur.id);s.p=s.h.length-1;s.ts=Date.now();db.set.hqst=s}}
 const s=hqState();HQ_OPENED=true;if(m==='prev'){if(s.p>0){s.p--;db.set.hqst=s}}else if(m==='next'){if(s.p<s.h.length-1){s.p++;db.set.hqst=s}else hqPick(P)}else hqPick(P);save()}
function heroQB(q){const c=heroCfg(),fv=q[3]&&qMap()[q[3]]?(zQT().fav.includes(q[3])?'★':'☆'):'';
 return'<p class="fa">«'+esc(q[0])+'»</p>'+(c.en!==false&&q[1]?'<p class="en">'+esc(q[1])+'</p>':'')+(c.au!==false&&q[2]?'<em>— '+esc(q[2])+'</em>':'')+'<div class="itu-qc"><button data-a="hq" data-k="prev" aria-label="قبلی">‹</button><button data-a="hq" data-k="new">🎲 غافلگیرم کن</button><button data-a="hq" data-k="next" aria-label="بعدی">›</button>'+(fv?'<button data-a="hq" data-k="fav">'+fv+'</button>':'')+'<button data-a="hq" data-k="cfg" aria-label="تنظیمات">⚙</button></div>'}
H.hq=e=>{const k=e.dataset.k,sk=SKINS[skId()],ch=sk&&sk.qchar;if(k==='cfg'){zMS.qt.tab='set';page='qt';render();return}if(!ch)return;
 if(k==='fav'){const q=heroQuote(ch);if(q&&q.id&&typeof zMA.qt.fav==='function')zMA.qt.fav(q.id);return}hqNav(k,ch);render()};
function qpCards(){const L=Object.values(QPACKS),sk=SKINS[skId()],ch=sk&&sk.qchar,c=heroCfg(),pool=ch?hqPool(ch):[],cur=ch?heroQuote(ch):null,chip=(on,k,l)=>'<button class="chip '+(on?'on':'')+'" data-a="qp" data-k="'+k+'">'+(on?'✓ ':'')+l+'</button>';
 let h='<div class="c" id="qpcard"><h3>بسته‌های جملات</h3><p class="m">فایل جملات دوزبانه (فارسی + انگلیسی) را وارد کن تا به «همه»، جمله‌ی روز و چرخش جمله‌ها اضافه شود. وارد کردن دوباره‌ی همان بسته فقط جمله‌های تازه را اضافه می‌کند. این بسته‌ها فقط داده‌اند و نیازی به حالت توسعه‌دهنده ندارند.</p><div class="row"><label class="btn" style="margin:0">وارد کردن بسته‌ی جملات<input type="file" accept=".json,application/json" data-qpfile style="display:none"></label></div>'
 +L.map(p=>'<div class="row" style="margin-top:6px"><b>'+esc(p.name)+'</b><span class="m">'+fa(p.quotes.length)+' جمله'+(p.character?' · شخصیت: '+esc(p.character):'')+'</span><span class="sp"></span><button class="d" data-a="qp" data-k="del:'+esc(p.id)+'">حذف</button></div>').join('')+(L.length?'':'<p class="m">هنوز بسته‌ای وارد نشده است.</p>')+'</div>';
 h+='<div class="c" id="qhcard"><h3>جمله‌ی بنر تم</h3>';
 if(!ch)return h+'<p class="m">تم فعلی کادر جمله‌ی بنر ندارد. یکی از تم‌های Itachi Uchiha را انتخاب کن (یا تمی که «شخصیت» جمله‌ها را تعریف کرده باشد).</p></div>';
 h+='<p class="m">تم فعلی: <b>'+esc(sk.name)+'</b> · شخصیت: '+esc(ch)+' · '+fa(pool.length)+' جمله مطابق انتخاب تو</p>'
 +(cur&&cur.fa?'<div class="qbig" style="margin:8px 0"><div class="qx"><div class="qfa">«'+esc(cur.fa)+'»</div>'+(cur.en?'<div class="qen">“'+esc(cur.en)+'”</div>':'')+'<div class="qat"><b>'+esc(cur.a)+'</b></div></div></div>':'')
 +'<div class="m">از چه منبعی بیاید؟</div><div class="row">'+chip(c.src==='char','src:char','جمله‌های این شخصیت')+chip(c.src==='all','src:all','همه‌ی جمله‌ها')+chip(c.src==='fav','src:fav','علاقه‌مندی‌ها')+'</div>'
 +'<div class="m" style="margin-top:8px">چطور عوض شود؟</div><div class="row">'+chip(c.mode==='rot','mode:rot','چرخشی (تصادفی)')+chip(c.mode==='daily','mode:daily','روزانه')+chip(c.mode==='pin','mode:pin','ثابت')+'<button data-a="qp" data-k="new">🎲 غافلگیرم کن</button></div>'
 +(c.mode==='rot'?'<label>هر چند دقیقه جمله عوض شود؟</label><select data-qpiv>'+[[0,'فقط با هر ورود'],[10,'هر ۱۰ دقیقه'],[20,'هر ۲۰ دقیقه'],[40,'هر ۴۰ دقیقه'],[60,'هر ساعت'],[120,'هر ۲ ساعت'],[240,'هر ۴ ساعت']].map(x=>'<option value="'+x[0]+'" '+(+c.iv===x[0]?'selected':'')+'>'+x[1]+'</option>').join('')+'</select>':'')
 +(c.mode==='pin'?'<label>جمله‌ی ثابت</label><select data-qppin>'+pool.slice(0,400).map(q=>'<option value="'+esc(q.id)+'" '+(c.pin===q.id?'selected':'')+'>'+esc((q.fa||'').slice(0,60))+'</option>').join('')+'</select>':'')
 +'<div class="row" style="margin-top:8px">'+(c.mode==='rot'?chip(c.open,'tog:open','با هر ورود به برنامه جمله‌ی تازه'):'')+chip(c.bi,'tog:bi','فقط جمله‌های دوزبانه')+chip(c.en!==false,'tog:en','نمایش متن انگلیسی')+chip(c.au!==false,'tog:au','نمایش گوینده')+'</div><p class="m">زیر جمله‌ی بنر هم دکمه‌های قبلی، غافلگیرم کن، بعدی، علاقه‌مندی و تنظیمات هست.</p></div>';return h}
H.qp=async e=>{const[m,v]=(e.dataset.k||'').split(':'),c=Object.assign({},heroCfg()),sk=SKINS[skId()],ch=sk&&sk.qchar;
 if(m==='mode'){c.mode=v;if(v==='pin'&&!c.pin&&ch){const P=hqPool(ch);if(P.length)c.pin=P[0].id}db.set.heroq=c;if(save())render()}
 else if(m==='src'){c.src=v;db.set.heroq=c;db.set.hqst={h:[],p:-1,ts:0};if(save())render()}
 else if(m==='tog'&&['open','bi','en','au'].includes(v)){c[v]=!c[v];db.set.heroq=c;if(v==='bi')db.set.hqst={h:[],p:-1,ts:0};if(save())render()}
 else if(m==='new'&&ch){hqNav('new',ch);render()}
 else if(m==='del'&&QPACKS[v]){if(!confirm('بسته‌ی «'+QPACKS[v].name+'» حذف شود؟ (داده‌های برنامه تغییری نمی‌کند)'))return;try{await IMG.del('qpack_'+v)}catch(x){}try{localStorage.removeItem('dani_qpack_'+v)}catch(x){}delete QPACKS[v];try{delete QTOP['pk_'+v]}catch(x){}if(save()){toast('بسته حذف شد');render()}}};
document.addEventListener('change',e=>{const t=e.target;if(!t.matches)return;if(t.matches('[data-qpfile]')){const f=t.files[0];t.value='';if(f)qpImport(f)}else if(t.matches('[data-qppin]')){db.set.heroq=Object.assign({},heroCfg(),{mode:'pin',pin:t.value});if(save())render()}else if(t.matches('[data-qpiv]')){db.set.heroq=Object.assign({},heroCfg(),{iv:+t.value||0});if(save())render()}});
setInterval(()=>{try{if(page==='home'&&document.querySelector('.itu-hq')&&hqDue())render()}catch(e){}},20000);

