async function skExport(){const k=skId(),S=SKINS[k],o={format:'hamrah-theme',version:1,id:S.custom?S.id:'my-'+S.id,name:S.custom?S.name:'My '+S.name,desc:S.desc,tag:S.tag,lay:S.lay,dark:S.dark,card:S.card,btn:S.btn,font:S.font,ic:S.ic,rad:S.rad,wm:S.wm};
 if(S.vars)o.vars=S.vars;if(S.bgGradient)o.bgGradient=S.bgGradient;if(S.hero){const{h,fit,pos,dim,size,bg,stripe}=S.hero;o.hero={h,fit,pos,dim,size,bg,stripe}}if(S.favicon)o.favicon=S.favicon;
 o.imgs=[];let miss=0;for(const i of S.imgs){let d=i.src;if(!d.startsWith('data:')){try{d=await new Promise((res,rej)=>{const im=new Image();im.onload=()=>{try{const c=document.createElement('canvas');c.width=im.width;c.height=im.height;c.getContext('2d').drawImage(im,0,0);res(c.toDataURL('image/jpeg',.88))}catch(e){rej(e)}};im.onerror=rej;im.src=i.src})}catch(e){miss++;continue}}o.imgs.push({id:i.id,name:i.name,data:d})}
 if(S.emblem&&o.imgs.some(i=>i.id===S.emblem.img))o.emblem=S.emblem;if(!vetTheme(JSON.parse(JSON.stringify(o)),true).ok)return toast('خروجی تم ساخته نشد',1);
 dl(o.id+'.hamrah-theme.json','application/json',JSON.stringify(o));if(miss)toast('تصاویر آماده در این حالت (فایل محلی) ضمیمه نشد',1)}
document.addEventListener('click',e=>{const t=e.target.closest('[data-sk],[data-skimg],[data-skdel],[data-skrm],[data-skexp]');if(!t)return;
 if(t.dataset.sk){if(!SKINS[t.dataset.sk])return;db.set.skin=t.dataset.sk;if(save())render()}
 else if(t.dataset.skimg){skSet(skId(),t.dataset.skimg);if(save())render()}
 else if('skexp' in t.dataset){skExport()}
 else if(t.dataset.skrm){const id=t.dataset.skrm,S=SKINS[id];if(!S||!S.custom||!confirm('تم «'+S.name+'» حذف شود؟ (داده‌های برنامه تغییری نمی‌کند)'))return;
  delete SKINS[id];db.set.dthemes=(Array.isArray(db.set.dthemes)?db.set.dthemes:[]).filter(x=>x!==id).concat(id).slice(-60);if(db.set.skin===id)db.set.skin='dani';try{IMG.del('theme_'+id).catch(()=>0)}catch(e){}if(STU&&STU.id===id){STU.open=false;STU.d=null;STU.id=null}if(save()){toast('تم حذف شد');render()}}
 else if('skdel' in t.dataset){const k=skId();if(!confirm('تصویر شما حذف شود؟'))return;IMG.del('skin_'+k).catch(()=>0).then(()=>{delete CUST[k];if(db.set.skinImg&&db.set.skinImg[k]==='custom')delete db.set.skinImg[k];if(save()){toast('حذف شد');render()}})}});
document.addEventListener('change',e=>{const t=e.target;if(!t.matches)return;if(t.matches('[data-skfile]')){skFile(t.files[0],skId());t.value=''}else if(t.matches('[data-skthemefile]')){skImport(t.files[0]);t.value=''}else if(t.matches('[data-skdim]')){db.set.skinDim=Math.min(.9,Math.max(.1,+t.value||.45));if(save())render()}});
(function(){try{const B=window.DANI_BAKED||{};(B.themes||[]).forEach(o=>{try{const r=vetTheme(o,true);if(r.ok&&!SK_BUILTIN.has(r.def.id)&&!(Array.isArray(db.set.dthemes)&&db.set.dthemes.includes(r.def.id)))SKINS[r.def.id]=r.def}catch(e){}});Object.entries(B.skinImg||{}).forEach(([k,v])=>{if(SKINS[k]&&typeof v==='string'&&/^(data:image\/|img\/)/.test(v))CUST[k]=v})}catch(e){}})();
(async()=>{try{for(const key of await IMG.keys()){if(typeof key==='string'&&key.startsWith('theme_')){try{const o=JSON.parse(await IMG.get(key)),r=vetTheme(o,true);if(r.ok&&!SK_BUILTIN.has(r.def.id)&&!(Array.isArray(db.set.dthemes)&&db.set.dthemes.includes(r.def.id)))SKINS[r.def.id]=r.def}catch(e){}}}
 for(const k of Object.keys(SKINS)){try{const v=await IMG.get('skin_'+k);if(v&&typeof v==='string'&&/^(data:image\/|img\/)/.test(v))CUST[k]=v}catch(e){}}}catch(e){}render()})();
